type Order =
  | { status: 'placed'; id: string; items: string[] }
  | { status: 'cooking'; id: string; items: string[]; station: 'grill' | 'fryer' | 'pastry' }
  | { status: 'served'; id: string; items: string[]; servedAt: number }
  | { status: 'cancelled'; id: string; reason: string };

function ticketLabel(order: Order): string {
  switch (order.status) {
    case 'placed': return `#${order.id} waiting (${order.items.length} items)`;
    case 'cooking': return `#${order.id} on ${order.station}`;
    case 'served': return `#${order.id} served at ${new Date(order.servedAt).toISOString()}`;
    case 'cancelled': return `#${order.id} cancelled: ${order.reason}`;
    default: {
      const unreachable: never = order; // compile error here if a status is added but not handled
      return unreachable;
    }
  }
}

// @ts-expect-error: a cancelled order cannot have a servedAt time
const impossible: Order = { status: 'cancelled', id: '7', reason: 'burnt', servedAt: 1 };

type KitchenEvents = {
  orderPlaced: { id: string; items: string[] };
  orderServed: { id: string; at: number };
  stationDown: { station: string };
};

type Listener<P> = (payload: P) => void;

class TypedEmitter<Events extends Record<string, unknown>> {
  private listeners: { [K in keyof Events]?: Set<Listener<Events[K]>> } = {};

  on<K extends keyof Events>(event: K, listener: Listener<Events[K]>): () => void {
    const set = (this.listeners[event] ??= new Set<Listener<Events[K]>>());
    set.add(listener);
    return () => { set.delete(listener); };
  }

  emit<K extends keyof Events>(event: K, payload: Events[K]): void {
    for (const listener of [...(this.listeners[event] ?? [])]) listener(payload);
  }
}

const bus = new TypedEmitter<KitchenEvents>();
bus.on('orderServed', e => console.log(e.at.toFixed(0))); // e is { id: string; at: number }
// @ts-expect-error: 'at' must be a number
bus.emit('orderServed', { id: '12', at: 'noon' });
// @ts-expect-error: unknown event name
bus.emit('orderLost', {});

function pipe<A, B>(ab: (a: A) => B): (a: A) => B;
function pipe<A, B, C>(ab: (a: A) => B, bc: (b: B) => C): (a: A) => C;
function pipe<A, B, C, D>(ab: (a: A) => B, bc: (b: B) => C, cd: (c: C) => D): (a: A) => D;
function pipe(...fns: Array<(x: unknown) => unknown>) {
  return (input: unknown) => fns.reduce((acc, fn) => fn(acc), input);
}

const priceTicket = pipe(
  (items: string[]) => items.length,
  (count: number) => count * 12.5,
  (total: number) => `$${total.toFixed(2)}`,
);
const label: string = priceTicket(['soup', 'bread']); // "$25.00"
// @ts-expect-error: the second step expects a number, not a string
pipe((items: string[]) => items.join(','), (count: number) => count * 2);

