codeExercise.solution:
const delay = (ms, value) => new Promise(resolve => setTimeout(() => resolve(value), ms));
async function poolReport(durations, limit) {
  let active = 0, maxActive = 0;
  const tasks = durations.map((ms, i) => () => {
    active += 1; maxActive = Math.max(maxActive, active);
    return delay(ms, `dish${i}`).then(v => { active -= 1; return v; });
  });
  const results = await promisePool(tasks, limit);
  return { results, maxActive };
}

function promisePool(tasks, limit) {
  return new Promise((resolve, reject) => {
    if (!(limit >= 1)) throw new RangeError('limit must be at least 1');
    const results = new Array(tasks.length);
    let next = 0, finished = 0, failed = false;
    if (tasks.length === 0) { resolve(results); return; }
    const launch = () => {
      if (failed || next >= tasks.length) return;
      const index = next++;
      Promise.resolve()
        .then(() => tasks[index]())
        .then(value => {
          results[index] = value;
          finished += 1;
          if (finished === tasks.length) resolve(results);
          else launch();
        }, error => { failed = true; reject(error); });
    };
    for (let i = 0; i < Math.min(limit, tasks.length); i++) launch();
  });
}

codeExercise.solutionNote:
**The plausible wrong answer:**

```js
function promisePool(tasks, limit) {
  const started = tasks.map(task => task()); // "they'll run later, the limit is applied below"
  return Promise.all(started);
}
```

This reveals **`async-control-flow.m1`**. The learner believes creating a promise schedules the work for later, so calling every task up front seems harmless. In fact each task starts the moment it's called, and `maxActive` equals the task count.

codeExercise.testSource:
describe('promisePool', () => {
  it('never exceeds the limit and keeps input order', async () => {
    const report = await poolReport([30, 10, 20, 5], 2);
    expect(report.maxActive).toBe(2);
    expect(report.results).toEqual(['dish0', 'dish1', 'dish2', 'dish3']);
  });
  it('handles a limit larger than the task count', async () => {
    expect(await poolReport([5, 5], 10)).toEqual({ results: ['dish0', 'dish1'], maxActive: 2 });
  });
  it('resolves an empty list to []', async () => {
    await expect(promisePool([], 3)).resolves.toEqual([]);
  });
  it('rejects when a task fails and does not start further tasks', async () => {
    const started = [];
    const tasks = [0, 1, 2, 3].map(i => () => {
      started.push(i);
      return i === 0 ? Promise.reject(new Error('oven down')) : delay(20, i);
    });
    await expect(promisePool(tasks, 1)).rejects.toThrow('oven down');
    expect(started).toEqual([0]);
  });
});

