// The `seen` map is the visited set of a graph traversal.
function deepClone(value, seen = new Map()) {
  // [[edit]]
  // primitives and null: return as-is
  // already in `seen`: return the existing copy
  // Date: new Date(time). Map / Set: new container, register in `seen` BEFORE copying entries
  // arrays and objects: new container with the same prototype, register, then copy own keys
  return value; // placeholder: returns the original, not a copy
  // [[/edit]]
}

codeExercise.solution:
function deepClone(value, seen = new Map()) {
  if (value === null || typeof value !== 'object') return value;
  if (seen.has(value)) return seen.get(value);
  if (value instanceof Date) return new Date(value.getTime());
  if (value instanceof Map) {
    const copy = new Map();
    seen.set(value, copy);
    for (const [k, v] of value) copy.set(deepClone(k, seen), deepClone(v, seen));
    return copy;
  }
  if (value instanceof Set) {
    const copy = new Set();
    seen.set(value, copy);
    for (const v of value) copy.add(deepClone(v, seen));
    return copy;
  }
  const copy = Array.isArray(value) ? [] : Object.create(Object.getPrototypeOf(value));
  seen.set(value, copy);
  for (const key of Object.keys(value)) copy[key] = deepClone(value[key], seen);
  return copy;
}

codeExercise.solutionNote:
**The plausible wrong answer:**

```js
function deepClone(value) {
  return value === undefined ? value : JSON.parse(JSON.stringify(value));
}
```

This throws on the cycle, turns `Date` into a string, and turns `Map` and `Set` into `{}`. It reveals **`ui-data-structures.m1`**: the learner treats the object as a tree of JSON rather than a graph that needs a traversal with a visited set.

codeExercise.testSource:
describe('deepClone', () => {
  it('copies nested structures so mutations do not leak', () => {
    const order = { table: 4, items: ['soup'] };
    const copy = deepClone(order);
    copy.items.push('tea');
    expect(order.items).toEqual(['soup']);
    expect(copy).toEqual({ table: 4, items: ['soup', 'tea'] });
  });
  it('copies Dates as Dates', () => {
    const copy = deepClone({ placed: new Date(1000) });
    expect(copy.placed).toBeInstanceOf(Date);
    expect(copy.placed.getTime()).toBe(1000);
  });
  it('preserves cycles', () => {
    const a = { name: 'ticket' }; a.self = a;
    const c = deepClone(a);
    expect(c).not.toBe(a);
    expect(c.self).toBe(c);
  });
  it('preserves shared references', () => {
    const shared = { station: 'grill' };
    const c = deepClone({ first: shared, second: shared });
    expect(c.first).toBe(c.second);
    expect(c.first).not.toBe(shared);
  });
  it('deep-copies Map and Set contents', () => {
    const m = new Map([['grill', new Set(['steak'])]]);
    const c = deepClone(m);
    c.get('grill').add('burger');
    expect(m.get('grill').size).toBe(1);
    expect(c.get('grill').size).toBe(2);
  });
  it('returns primitives and null unchanged', () => {
    expect(deepClone(null)).toBeNull();
    expect(deepClone(7)).toBe(7);
    expect(deepClone({})).toEqual({});
  });
});

