// Provided (locked): a manual clock so tests control time (the engine has no fake timers)
function createManualScheduler() {
  let now = 0, nextId = 1;
  const timers = new Map();
  return {
    now: () => now,
    setTimeout(fn, ms) { const id = nextId++; timers.set(id, { at: now + ms, fn }); return id; },
    clearTimeout(id) { timers.delete(id); },
    advance(ms) {
      const target = now + ms;
      for (;;) {
        let dueId = null, due = null;
        for (const [id, t] of timers) if (t.at <= target && (!due || t.at < due.at)) { dueId = id; due = t; }
        if (!due) break;
        timers.delete(dueId); now = due.at; due.fn();
      }
      now = target;
    },
  };
}
// Provided (locked): run a list of [time, arg] calls ('cancel' cancels) and log when fn ran
function debounceScenario(options, calls, until) {
  const s = createManualScheduler();
  const log = [];
  const d = debounce(x => log.push(`${s.now()}:${x}`), 100, { ...options, scheduler: s });
  let t = 0;
  for (const [at, arg] of calls) { s.advance(at - t); t = at; if (arg === 'cancel') d.cancel(); else d(arg); }
  s.advance(until - t);
  return log;
}

function debounce(fn, wait, options = {}) {
  const { leading = false, trailing = true, scheduler = globalThis } = options;
  // [[edit]]
  // closure state: the pending timer id and the latest arguments and `this`
  function debounced(...args) {
    // remember the latest args; if this call starts a burst and leading is on, call fn now
    // (re)start the quiet-period timer; when it fires, call fn with the LATEST args if trailing
  }
