codeExercise.solution:
const ok = value => ({ ok: true, value });
const fail = error => ({ ok: false, error });

function parseOrderEvent(input) {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) return fail('expected an object');
  const { type, id } = input;
  if (typeof id !== 'string' || id.length === 0) return fail('id must be a non-empty string');
  switch (type) {
    case 'placed':
      if (!Array.isArray(input.items) || !input.items.every(i => typeof i === 'string')) return fail('items must be an array of strings');
      return ok({ type, id, items: [...input.items] });
    case 'cancelled':
      if (typeof input.reason !== 'string') return fail('reason must be a string');
      return ok({ type, id, reason: input.reason });
    case 'served':
      if (typeof input.at !== 'number' || !Number.isFinite(input.at)) return fail('at must be a finite number');
      return ok({ type, id, at: input.at });
    default:
      return fail(`unknown type: ${String(type)}`);
  }
}

