function createEmitter() {
  const listeners = {};
  return {
    on(event, fn) {
      (listeners[event] = listeners[event] || []).push(fn);
      return () => {
        const list = listeners[event];
        const index = list.indexOf(fn);
        if (index !== -1) list.splice(index, 1); // bug 2: indexOf -1 used to splice the LAST listener
      };
    },
    once(event, fn) {
      const off = this.on(event, payload => { off(); fn(payload); });
      return off;
    },
    emit(event, payload) {
      const list = listeners[event];
      if (!list) return;                          // bug 1: no listeners threw a TypeError
      for (const listener of [...list]) listener(payload); // bug 3: iterate a snapshot so removal mid-emit can't skip
    },
  };
}

