function parseDirectives(header) {
  const out = {};
  for (const part of (header || '').split(',')) {
    const [name, value] = part.trim().split('=');
    if (name) out[name.trim().toLowerCase()] = value === undefined ? true : Number(value);
  }
  return out;
}

function decideCacheUse(cacheControl, ageSeconds, validators = {}) {
  const d = parseDirectives(cacheControl);
  const canValidate = Boolean(validators.etag || validators.lastModified);
  const fallback = canValidate ? 'revalidate' : 'refetch';
  if (d['no-store']) return 'do-not-store';
  if (d['no-cache']) return fallback;
  const maxAge = typeof d['max-age'] === 'number' ? d['max-age'] : null;
  if (maxAge === null) return fallback;
  if (ageSeconds < maxAge) return 'use-cached';
