function corsOutcome(request, responseHeaders) {
  const allowOrigin = responseHeaders['access-control-allow-origin'];
  const allowCredentials = responseHeaders['access-control-allow-credentials'] === 'true';
  const result = (jsCanRead, reason) => ({ serverProcessed: true, jsCanRead, reason });
  if (!allowOrigin) return result(false, 'missing Access-Control-Allow-Origin');
  if (request.credentials) {
    if (allowOrigin === '*') return result(false, 'wildcard not allowed with credentials');
    if (allowOrigin !== request.origin) return result(false, 'origin mismatch');
    if (!allowCredentials) return result(false, 'credentials not allowed');
    return result(true, 'allowed');
  }
  if (allowOrigin === '*' || allowOrigin === request.origin) return result(true, 'allowed');
  return result(false, 'origin mismatch');
}

