function createMemoryStorage(quotaChars = 5000) {
  const data = new Map();
  const size = () => [...data].reduce((n, [k, v]) => n + k.length + v.length, 0);
  return {
    getItem: key => (data.has(key) ? data.get(key) : null),
    setItem(key, value) {
      const str = String(value);
      const previous = data.get(key);
      data.set(key, str);
      if (size() > quotaChars) {
        if (previous === undefined) data.delete(key); else data.set(key, previous);
        const err = new Error('The quota has been exceeded.');
        err.name = 'QuotaExceededError';
        throw err;
      }
    },
    removeItem: key => { data.delete(key); },
  };
}

function createPrefsStore(storage, key = 'prefs', defaults = { theme: 'light', fontScale: 1 }) {
  return {
    load() {
      return storage.getItem(key) || defaults;
    },
    save(prefs) {
      storage.setItem(key, prefs);
      return true;
    },
  };
}

