function useState(initial) {
  const rt = currentRuntime;
  const i = rt.nextIndex('useState');
  if (!(i in rt.hooks)) rt.hooks[i] = { value: typeof initial === 'function' ? initial() : initial };
  const slot = rt.hooks[i];
  slot.setState ??= next => {
    const value = typeof next === 'function' ? next(slot.value) : next;
    if (Object.is(value, slot.value)) return; // bail out: nothing to render
    slot.value = value;
    rt.requestRender();                        // batched: flushed once later
  };
  return [slot.value, slot.setState];
}

function useEffect(effect, deps) {
  const rt = currentRuntime;
  const i = rt.nextIndex('useEffect');
  const prev = rt.hooks[i];
  const changed = !prev || !deps || !prev.deps ||
    deps.length !== prev.deps.length || deps.some((d, k) => !Object.is(d, prev.deps[k]));
  if (!changed) return;
  const slot = { deps, cleanup: prev && prev.cleanup };
  rt.hooks[i] = slot;
  rt.afterCommit(() => {
    if (typeof slot.cleanup === 'function') slot.cleanup(); // undo the previous synchronization
    const cleanup = effect();
    slot.cleanup = typeof cleanup === 'function' ? cleanup : undefined;
  });
}

