function whoRenders(tree, trigger) {
  const rendered = [], committed = [];
  function walk(node, parentRendered) {
    const skippedByMemo = node.memo && !node.propsChanged;
    const ownTrigger = trigger.state === node.name || (trigger.context !== undefined && node.context === trigger.context);
    const renders = ownTrigger || (parentRendered && !skippedByMemo);
    if (renders) {
      rendered.push(node.name);
      if (node.outputChanged) committed.push(node.name);
    }
    (node.children || []).forEach(child => walk(child, renders));
  }
  walk(tree, false);
  return { rendered, committed };
}

