codeExercise.solution:
function flattenObject(root) {
  const out = {};
  const isContainer = v => v !== null && typeof v === 'object' && !(v instanceof Date);
  if (!isContainer(root)) return out;
  const stack = [[root, '']];
  while (stack.length) {
    const [value, path] = stack.pop();
    const keys = isContainer(value) ? Object.keys(value) : null;
    if (!keys || (keys.length === 0 && path)) { out[path] = value; continue; }
    for (let i = keys.length - 1; i >= 0; i--) stack.push([value[keys[i]], path ? `${path}.${keys[i]}` : keys[i]]);
  }
  return out;
}

