class LinkedLRU {
  constructor(capacity) {
    this.capacity = capacity;
    this.index = new Map();
    this.head = { prev: null, next: null };
    this.tail = { prev: null, next: null };
    this.head.next = this.tail; this.tail.prev = this.head;
  }
  _unlink(node) { node.prev.next = node.next; node.next.prev = node.prev; }
  _append(node) { node.prev = this.tail.prev; node.next = this.tail; this.tail.prev.next = node; this.tail.prev = node; }
  get(key) {
    const node = this.index.get(key);
    if (!node) return undefined;
    this._unlink(node); this._append(node);
    return node.value;
  }
  set(key, value) {
    let node = this.index.get(key);
    if (node) { node.value = value; this._unlink(node); }
    else { node = { key, value }; this.index.set(key, node); }
    this._append(node);
    if (this.index.size > this.capacity) {
      const oldest = this.head.next;
      this._unlink(oldest);
      this.index.delete(oldest.key);
    }
