const circular = { 'a.js': ['b.js'], 'b.js': ['c.js'], 'c.js': ['a.js'], 'd.js': [] };
const errorOf = fn => { try { fn(); return 'no error'; } catch (e) { return e.message; } };
function topoSort(graph) {
  const nodes = [];
  const known = new Set();
  const add = n => { if (!known.has(n)) { known.add(n); nodes.push(n); } };
  for (const [node, deps] of Object.entries(graph)) { add(node); deps.forEach(add); }
  const indegree = new Map(nodes.map(n => [n, 0]));
  const dependents = new Map(nodes.map(n => [n, []]));
  for (const [node, deps] of Object.entries(graph)) {
    for (const dep of deps) { indegree.set(node, indegree.get(node) + 1); dependents.get(dep).push(node); }
  }
  const queue = nodes.filter(n => indegree.get(n) === 0);
  const order = [];
  for (let head = 0; head < queue.length; head++) {
    const n = queue[head];
    order.push(n);
    for (const d of dependents.get(n)) {
      indegree.set(d, indegree.get(d) - 1);
      if (indegree.get(d) === 0) queue.push(d);
    }
  }
  if (order.length !== nodes.length) {
    const placed = new Set(order);
    const remaining = nodes.filter(n => !placed.has(n));
    const position = new Map();
    const path = [];
    let current = remaining[0];
    while (!position.has(current)) {
      position.set(current, path.length);
      path.push(current);
      current = (graph[current] || []).find(dep => !placed.has(dep));
    }
    const cycle = path.slice(position.get(current)).concat(current);
    throw new Error(`Cycle detected: ${cycle.join(' -> ')}`);
  }
  return order;
}

