] };

function nodesAtDepth(root, depth) {
  if (!root || depth < 0) return [];
  const queue = [[root, 0]];
  const out = [];
  for (let head = 0; head < queue.length; head++) {
    const [node, d] = queue[head];
    if (d === depth) { out.push(node.name); continue; }       // no need to go deeper
    for (const child of node.children || []) queue.push([child, d + 1]);
  }
  return out;
}

