const payload = { trips: [
  { id: 't1', title: 'Lisbon', owner: { id: 'u1', name: 'Ana' }, members: [{ id: 'u2', name: 'Ben' }] },
  { id: 't2', title: 'Kyoto', owner: { id: 'u2', name: 'Ben' }, members: [{ id: 'u1', name: 'Ana' }, { id: 'u3', name: 'Chi' }] },
] };
function storeScenario(run) { const store = createTripStore(); run(store); return store.getState(); }
function createTripStore() {
  let state = { entities: { users: {}, trips: {} }, tripOrder: [], ui: { expandedTripId: null, draftComment: '' } };
  return {
    getState: () => state,
    receiveTrips(apiPayload) {
      const users = {}, trips = {}, tripOrder = [];
      for (const trip of apiPayload.trips) {
        for (const u of [trip.owner, ...trip.members]) users[u.id] = { id: u.id, name: u.name };
        trips[trip.id] = { id: trip.id, title: trip.title, ownerId: trip.owner.id, memberIds: trip.members.map(m => m.id) };
        tripOrder.push(trip.id);
      }
      state = { ...state, entities: { users, trips }, tripOrder };
    },
    renameUser(id, name) {
      const user = state.entities.users[id];
      if (!user) return;
      state = { ...state, entities: { ...state.entities, users: { ...state.entities.users, [id]: { ...user, name } } } };
    },
    setUi(patch) { state = { ...state, ui: { ...state.ui, ...patch } }; },
  };
}
const selectTripCards = (() => {
  let lastEntities = null, lastOrder = null, lastResult = null;
  return state => {
    if (state.entities === lastEntities && state.tripOrder === lastOrder) return lastResult;
    const { users, trips } = state.entities;
    lastResult = state.tripOrder.map(id => {
      const t = trips[id];
      return { id, title: t.title, ownerName: users[t.ownerId].name, memberNames: t.memberIds.map(m => users[m].name) };
    });
    lastEntities = state.entities; lastOrder = state.tripOrder;
    return lastResult;
  };
})();

