codeExercise.solution:
function countingArray(items) {
  let reads = 0;
  const proxy = new Proxy(items, { get(t, p, r) { if (typeof p === 'string' && /^\d+$/.test(p)) reads++; return Reflect.get(t, p, r); } });
  return { proxy, reads: () => reads };
}
const heights = [100, 50, 200, 80, 120];
function buildOffsets(heights) {
  const offsets = [0];
  for (const h of heights) offsets.push(offsets[offsets.length - 1] + h);
  return offsets;
}
function firstIndexWhere(offsets, lo, hi, pred) {
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (pred(offsets[mid])) hi = mid; else lo = mid + 1;
  }
  return lo;
}
function findVisibleRange(offsets, scrollTop, viewportHeight, overscan = 0) {
  const count = offsets.length - 1;
  if (count <= 0) return { start: 0, end: 0 };
  const start = Math.max(0, firstIndexWhere(offsets, 1, count, v => v > scrollTop) - 1);
  const end = firstIndexWhere(offsets, 0, count, v => v >= scrollTop + viewportHeight);
  return { start: Math.max(0, start - overscan), end: Math.min(count, Math.max(end, start + 1) + overscan) };
}
function anchorScrollTop(oldOffsets, newOffsets, scrollTop) {
  const { start } = findVisibleRange(oldOffsets, scrollTop, 1, 0);
  const delta = scrollTop - oldOffsets[start];
  return newOffsets[start] + delta;
}

