function findVisibleRange(offsets, scrollTop, viewportHeight, overscan = 0) {
  const count = offsets.length - 1;
  if (count <= 0) return { start: 0, end: 0 };
  const idx = [...Array(count).keys()];
  const start = idx.findIndex(i => offsets[i + 1] > scrollTop);                    // "findIndex is fast"
  let end = idx.findIndex(i => offsets[i] >= scrollTop + viewportHeight); if (end === -1) end = count;
  return { start: Math.max(0, start - overscan), end: Math.min(count, Math.max(end, start + 1) + overscan) };
}
function anchorScrollTop(oldOffsets, newOffsets, scrollTop) { const { start } = findVisibleRange(oldOffsets, scrollTop, 1, 0); return newOffsets[start] + scrollTop - oldOffsets[start]; }
```

It gets correct ranges with around 100,000 reads per scroll event. It reveals **`algorithmic-pattern-recognition.m2`**: treating `findIndex` as constant-time inside a hot path.

