  };
}

describe('createUndoStack', () => {
  it('round-trips undo and redo', () => {
    const h = createUndoStack();
    h.push('v1');
    let doc = 'v2';
    doc = h.undo(doc); expect(doc).toBe('v1');
    doc = h.redo(doc); expect(doc).toBe('v2');
  });
  it('clears redo history on a new edit', () => {
    const h = createUndoStack();
    h.push('v1');
    let doc = h.undo('v2');
    h.push(doc);
    expect(h.canRedo()).toBe(false);
    expect(h.redo('v3')).toBe('v3');
  });
  it('drops the oldest entries past capacity', () => {
    const h = createUndoStack({ capacity: 2 });
    h.push('v1'); h.push('v2'); h.push('v3');
    let doc = 'v4';
    doc = h.undo(doc); doc = h.undo(doc);
