const bookings = [
  { id: 'b1', traveler: 'Ana Silva', city: 'Lisbon', nights: 3 },
  { id: 'b2', traveler: 'ben okafor', city: 'Kyoto', nights: 5 },
  { id: 'b3', traveler: 'Chi Nguyen', city: 'Lisbon', nights: 3 },
  { id: 'b4', traveler: 'Ben Adler', city: 'Oslo', nights: 2 },
];

function queryTable(rows, { sortBy, direction = 'asc', filter = '', page = 1, pageSize = 20 } = {}) {
  const needle = filter.trim().toLowerCase();
  let out = needle ? rows.filter(r => r.traveler.toLowerCase().includes(needle)) : rows.slice();
  if (sortBy) {
    const sign = direction === 'desc' ? -1 : 1;
    out.sort((a, b) => (a[sortBy] < b[sortBy] ? -1 : a[sortBy] > b[sortBy] ? 1 : 0) * sign); // stable; ties keep order
  }
  const start = (page - 1) * pageSize;
  return { rows: out.slice(start, start + pageSize).map(r => r.id), total: out.length };
}

