function longestSlice(items, budgetMs) {
  let sliceStart = 0, clock = 0, longest = 0, yields = 0;
  for (const cost of items) {
    if (clock - sliceStart >= budgetMs) { longest = Math.max(longest, clock - sliceStart); sliceStart = clock; yields++; }
    clock += cost;
  }
  longest = Math.max(longest, clock - sliceStart);
  return { longest, yields };
}
