async function processInChunks(items, work, { budgetMs = 50, now, yieldToMain }) {
  const results = [];
  let yields = 0;
  let sliceStart = now();
  for (const item of items) {
    if (now() - sliceStart >= budgetMs) {
      await yieldToMain();
      yields++;
      sliceStart = now();
    }
    results.push(work(item));
  }
  return { results, yields };
}

