function createFocusTrap(doc, containerId) {
  let opener = null, active = false;
  return {
    activate() {
      opener = doc.activeElement;
      active = true;
      doc.setAttribute(containerId, 'aria-modal', 'true');
      const inside = doc.tabbables(containerId);
      if (inside.length) doc.focus(inside[0]);
    },
