function validateForm(fields, values) {
  const summary = [], attrs = {};
  for (const field of fields) {
    const value = (values[field.id] || '').trim();
    let message = null;
    if (field.required && !value) message = `Enter ${field.label.toLowerCase()}`;
    else if (value && field.pattern && !field.pattern.test(value)) message = field.patternMessage;
    const describedBy = [field.hintId, message ? `${field.id}-error` : null].filter(Boolean);
