codeExercise.solution:
function tabsKeyDown(state, key) {
  const n = state.tabs.length;
  const to = i => ({ ...state, selected: ((i % n) + n) % n });
  switch (key) {
    case 'ArrowRight': return to(state.selected + 1);
    case 'ArrowLeft': return to(state.selected - 1);
    case 'Home': return to(0);
    case 'End': return to(n - 1);
    default: return state;
  }
}

