const bankFiles = {
  '/src/main.js': "import { formatMoney } from './format.js';\nimport { balance } from './account.js';\nconsole.log('main: ' + formatMoney(balance));",
  '/src/account.js': "import { cents } from './format.js';\nconsole.log('account loaded');\nexport const balance = cents(125050);",
  '/src/format.js': "console.log('format loaded');\nexport function cents(n) { return n / 100; }\nexport function formatMoney(v) { return '$' + v.toFixed(2); }",
};
function bundleAndRun(files, entry) {
  try {
    const { order, code } = bundle(files, entry);
    const logs = [];
    new Function('console', code)({ log: (...a) => logs.push(a.join(' ')) });
    return { order, logs };
  } catch (e) { return { error: e.message }; }
}
function resolvePath(from, spec) {
  if (!spec.startsWith('./') && !spec.startsWith('../')) return null;
  const parts = from.split('/').slice(0, -1);
  for (const seg of spec.split('/')) { if (seg === '.' || seg === '') continue; if (seg === '..') parts.pop(); else parts.push(seg); }
  return parts.join('/');
}
const IMPORT_RE = /^\s*import\s+(?:(\w+)|\{([^}]*)\})\s+from\s+['"]([^'"]+)['"];?[ \t]*$/gm;
const SIDE_EFFECT_RE = /^\s*import\s+['"]([^'"]+)['"];?[ \t]*$/gm;

function importSpecifiers(source) {
  return [...source.matchAll(/^\s*import\s+(?:[\w{}\s,]+?\s+from\s+)?['"]([^'"]+)['"]/gm)].map(m => m[1]);
}
function transform(source, resolve) {
  const exported = [];
  const code = source
    .replace(IMPORT_RE, (_, def, named, spec) => {
      const id = JSON.stringify(resolve(spec));
      if (def) return `const ${def} = __require(${id}).default;`;
      const bindings = named.split(',').map(s => s.trim()).filter(Boolean).map(s => { const [a, b] = s.split(/\s+as\s+/); return b ? `${a}: ${b}` : a; });
      return `const { ${bindings.join(', ')} } = __require(${id});`;
    })
    .replace(SIDE_EFFECT_RE, (_, spec) => `__require(${JSON.stringify(resolve(spec))});`)
    .replace(/^export\s+default\s+/gm, '__exports.default = ')
    .replace(/^export\s+(const|let|function)\s+(\w+)/gm, (_, kw, name) => { exported.push(name); return `${kw} ${name}`; });
  return code + exported.map(n => `\n__exports.${n} = ${n};`).join('');
}
function bundle(files, entry) {
  if (!(entry in files)) throw new Error(`Cannot resolve entry ${entry}`);
  const order = [], state = new Map(), stack = [], resolved = new Map();
  function visit(path) {
    if (state.get(path) === 'done') return;
    if (state.get(path) === 'visiting') throw new Error(`Cycle detected: ${[...stack.slice(stack.indexOf(path)), path].join(' -> ')}`);
    state.set(path, 'visiting'); stack.push(path);
    const map = new Map();
    for (const spec of importSpecifiers(files[path])) {
      const target = resolvePath(path, spec);
      if (!target || !(target in files)) throw new Error(`Cannot resolve '${spec}' from ${path}`);
      map.set(spec, target);
      visit(target);
    }
    resolved.set(path, map);
    stack.pop(); state.set(path, 'done'); order.push(path);
  }
  visit(entry);
  const modules = order.map(p => `${JSON.stringify(p)}: function (__require, __exports) {\n${transform(files[p], spec => resolved.get(p).get(spec))}\n}`).join(',\n');
  const code = `const modules = {\n${modules}\n};\nconst cache = {};\nfunction __require(id) {\n  if (cache[id]) return cache[id];\n  const exports = (cache[id] = {});\n  modules[id](__require, exports);\n  return exports;\n}\n__require(${JSON.stringify(entry)});`;
  return { order, code };
}

