function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h >>> 0;
}
const instantTransfers = { key: 'instant-transfers', rolloutPercent: 20, environments: ['production', 'preview'], overrides: { 'u-qa': true, 'u-1003': false }, killed: false };
function evaluateFlag(flag, user, env) {
  if (flag.killed) return { on: false, reason: 'killed' };
  if (flag.overrides && Object.prototype.hasOwnProperty.call(flag.overrides, user.id)) return { on: Boolean(flag.overrides[user.id]), reason: 'override' };
  if (flag.environments && !flag.environments.includes(env)) return { on: false, reason: 'environment' };
  const bucket = fnv1a(`${flag.key}:${user.id}`) % 100;
  return { on: bucket < (flag.rolloutPercent || 0), reason: 'rollout' };
}
function staleFlags(flags, today) {
  return flags.filter(f => (f.killed || f.rolloutPercent === 100) && today - f.changedOnDay > 30).map(f => f.key);
}

codeExercise.solutionNote:
**The plausible wrong answer:**

```js
function evaluateFlag(flag, user, env) {
  if (flag.overrides && Object.prototype.hasOwnProperty.call(flag.overrides, user.id)) return { on: Boolean(flag.overrides[user.id]), reason: 'override' };
  if (flag.killed) return { on: false, reason: 'killed' }; // kill switch checked too late
  if (flag.environments && !flag.environments.includes(env)) return { on: false, reason: 'environment' };
  return { on: fnv1a(`${flag.key}:${user.id}`) % 100 < (flag.rolloutPercent || 0), reason: 'rollout' };
}
function staleFlags(flags, today) { return flags.filter(f => (f.killed || f.rolloutPercent === 100) && today - f.changedOnDay > 30).map(f => f.key); }
```

The starter's `return { on: Boolean(flag.enabled) }` is what someone writes if they believe **`build-and-delivery-pipeline.m2`** (a flag is just an if statement). There's no rollout, no override, no kill switch, and no lifecycle. This subtler version also comes from treating a flag as a simple `if` rather than a policy with a defined order. The kill switch can't stop QA overrides during an incident.

