function reporterScenario() {
  const sent = [];
  const r = createErrorReporter({ release: '4f2c9e1', send: e => sent.push(e), maxBreadcrumbs: 3 });
  r.setContext({ route: '/transfer', flags: { instantTransfers: true } });
  ['nav /accounts', 'nav /transfer', 'click Send', 'POST /api/transfers/88123 502'].forEach(b => r.addBreadcrumb(b));
  const err = new Error('Payee bank 20417 rejected transfer 88123'); err.name = 'TransferError';
  r.capture(err);
  return sent[0];
}
function createErrorReporter({ release, send, maxBreadcrumbs = 5 }) {
  const crumbs = [];
  let context = { route: null, flags: {} };
  const mask = text => String(text).replace(/\d{4,}/g, digits => '#'.repeat(digits.length));
  return {
    addBreadcrumb(text) { crumbs.push(mask(text)); if (crumbs.length > maxBreadcrumbs) crumbs.shift(); },
    setContext(patch) { context = { ...context, ...patch }; },
    capture(error) {
      const event = {
        fingerprint: `${error.name}: ${String(error.message).replace(/\d+/g, '<n>')}`,
        message: mask(error.message),
        release,
        route: context.route,
        flags: { ...context.flags },
        breadcrumbs: [...crumbs],
      };
      send(event);
      return event;
    },
  };
}

codeExercise.solutionNote:
**The plausible wrong answer:**

```js
function createErrorReporter({ release, send }) {
  return {
    addBreadcrumb() {}, setContext() {},
    capture(error) { const event = { fingerprint: error.message, message: error.message, release }; send(event); return event; },
  };
}
```

The starter's `{ message: error.message }` is the "we have error tracking" version of **`build-and-delivery-pipeline.m3`** (shipped means done). Events arrive, but without the release, flags, or breadcrumbs nobody can tie them to the rollout or reproduce them, and they leak account numbers.

