    setTimeout(fn, ms) { const id = nextId++; timers.set(id, { at: now + ms, fn }); return id; },
    clearTimeout(id) { timers.delete(id); },
    advance(ms) { const target = now + ms; for (;;) { let id = null, t = null; for (const [k, v] of timers) if (v.at <= target && (!t || v.at < t.at)) { id = k; t = v; } if (!t) break; timers.delete(id); now = t.at; t.fn(); } now = target; },
  };
