  const set = patch => { state = { ...state, ...patch }; };
  let timer = null, controller = null, latest = '';
  function input(query) {
    latest = query;
    if (timer !== null) { scheduler.clearTimeout(timer); timer = null; }
    if (controller) { controller.abort(); controller = null; }
    const q = query.trim().toLowerCase();
    if (q.length < minChars) { set({ query, status: 'idle', results: [], error: null }); return; }
    if (cache.has(q)) { set({ query, status: 'success', results: cache.get(q), error: null }); return; }
    set({ query, status: 'debouncing', error: null });
    timer = scheduler.setTimeout(() => { timer = null; run(q, query); }, debounceMs);
  }
  function run(q, raw) {
