describe('validateTransfer', () => {
  const account = { balanceCents: 50000, dailyLimitCents: 100000, sentTodayCents: 0 };
  it('converts amounts to exact cents without floating-point error', () => {
    expect(validateTransfer('0.29', account)).toEqual({ ok: true, amountCents: 29 });
    expect(validateTransfer('12.3', account)).toEqual({ ok: true, amountCents: 1230 });
    expect(validateTransfer(' 5 ', account)).toEqual({ ok: true, amountCents: 500 });
