    expect(validateTransfer('500.01', account)).toEqual({ ok: false, error: 'Insufficient funds' });
  });
});

codeExercise.solution:
function validateTransfer(input, { balanceCents, dailyLimitCents, sentTodayCents }) {
  const text = String(input).trim();
  const match = /^(\d+)(?:\.(\d{1,2}))?$/.exec(text);
  if (!match) return { ok: false, error: 'Enter an amount like 12.50' };
  const amountCents = Number(match[1]) * 100 + Number((match[2] || '').padEnd(2, '0'));
  if (amountCents <= 0) return { ok: false, error: 'Amount must be more than $0.00' };
  if (amountCents > balanceCents) return { ok: false, error: 'Insufficient funds' };
  if (sentTodayCents + amountCents > dailyLimitCents) return { ok: false, error: 'Daily limit reached' };
  return { ok: true, amountCents };
}

