codeExercise.solution:
function compareSpecificity(x, y) {
  return x[0] - y[0] || x[1] - y[1] || x[2] - y[2];
}
function splitTopLevel(list) {
  const parts = []; let depth = 0, start = 0;
  for (let i = 0; i < list.length; i++) {
    const ch = list[i];
    if (ch === '(' || ch === '[') depth++;
    else if (ch === ')' || ch === ']') depth--;
    else if (ch === ',' && depth === 0) { parts.push(list.slice(start, i)); start = i + 1; }
  }
  parts.push(list.slice(start));
  return parts.map(p => p.trim()).filter(Boolean);
}
function specificity(selector) {
  let a = 0, b = 0, c = 0, i = 0;
  const s = selector.trim();
  const ident = () => { const start = i; while (i < s.length && /[\w-]/.test(s[i])) i++; return s.slice(start, i); };
  const closing = open => { let depth = 1, j = open + 1; while (j < s.length && depth) { if (s[j] === '(') depth++; else if (s[j] === ')') depth--; j++; } return j; };
  while (i < s.length) {
    const ch = s[i];
    if (ch === '#') { i++; ident(); a++; }
    else if (ch === '.') { i++; ident(); b++; }
    else if (ch === '[') { while (i < s.length && s[i] !== ']') i++; i++; b++; }
    else if (ch === ':' && s[i + 1] === ':') { i += 2; ident(); c++; }
    else if (ch === ':') {
      i++;
      const name = ident().toLowerCase();
      if (s[i] === '(') {
        const end = closing(i);
        const inner = s.slice(i + 1, end - 1);
        i = end;
        if (name === 'where') continue;
        if (name === 'is' || name === 'not' || name === 'has') {
          const best = splitTopLevel(inner).map(specificity).sort((x, y) => compareSpecificity(y, x))[0] || [0, 0, 0];
          a += best[0]; b += best[1]; c += best[2];
        } else b++;
      } else b++;
    }
    else if (/[a-zA-Z]/.test(ch)) { ident(); c++; }
    else i++; // '*', combinators, whitespace
  }
  return [a, b, c];
}

