codeExercise.solution:
const LAYERS = ['reset', 'tokens', 'base', 'components', 'utilities'];
const d = (value, layer, specificity, order, important = false) => ({ value, layer, specificity, order, important });
function resolveCascade(declarations, layerOrder) {
  const rank = decl => (decl.layer == null ? layerOrder.length : layerOrder.indexOf(decl.layer));
  const layerPrecedence = decl => (decl.important ? -rank(decl) : rank(decl));
  const sorted = [...declarations].sort((x, y) =>
    (Number(y.important) - Number(x.important))
    || (layerPrecedence(y) - layerPrecedence(x))
    || (y.specificity[0] - x.specificity[0]) || (y.specificity[1] - x.specificity[1]) || (y.specificity[2] - x.specificity[2])
    || (y.order - x.order));
  return sorted.length ? sorted[0].value : undefined;
}

