function styleRuntimeWork(approach, renders) {
  const staticApproaches = ['utilities', 'css-modules', 'zero-runtime'];
  if (staticApproaches.includes(approach)) return { serializations: 0, insertedRules: 0, dynamicVia: 'custom-properties' };
  if (approach !== 'runtime-css-in-js') throw new Error(`Unknown approach: ${approach}`);
  const keyOf = props => JSON.stringify(Object.keys(props).sort().map(k => [k, props[k]]));
  const distinct = new Set(renders.map(keyOf));
  return { serializations: renders.length, insertedRules: distinct.size, dynamicVia: 'generated-rules' };
}

