function matchesMedia(query, viewportPx) {
  const clause = query.split(' and ')[0];
  const m = /\((min|max)-width:\s*([\d.]+)(px|em|rem)\)/.exec(clause);
  if (!m) return false;
  const value = parseFloat(m[2]);
  return m[1] === 'min' ? viewportPx > value : viewportPx < value;
}

