codeExercise.solution:
function matchesMedia(query, viewportPx) {
  const clauses = query.split(/\s+and\s+/);
  return clauses.every(clause => {
    const m = /^\((min|max)-width:\s*([\d.]+)(px|em|rem)\)$/.exec(clause.trim());
    if (!m) return false;
    const px = parseFloat(m[2]) * (m[3] === 'px' ? 1 : 16);
    return m[1] === 'min' ? viewportPx >= px : viewportPx <= px;
  });
}

