codeExercise.solution:
function createSpring({ mass = 1, stiffness = 170, damping = 26, from = 0, to = 1, velocity = 0, restDelta = 0.001, restSpeed = 0.01 } = {}) {
  let x = from, v = velocity, target = to;
  return {
    step(dt) {
      const force = -stiffness * (x - target) - damping * v;
      v += (force / mass) * dt;
      x += v * dt;
      return { x, v };
    },
    get position() { return x; },
    get velocity() { return v; },
    retarget(next) { target = next; },
    isAtRest() { return Math.abs(v) < restSpeed && Math.abs(x - target) < restDelta; },
  };
}
function simulate(options, { dt = 1 / 120, maxSteps = 2000 } = {}) {
  const spring = createSpring(options);
  const start = options.from ?? 0, end = options.to ?? 1;
  let peak = start, steps = 0;
  while (!spring.isAtRest() && steps < maxSteps) {
    spring.step(dt);
    steps++;
    if (end >= start ? spring.position > peak : spring.position < peak) peak = spring.position;
  }
  const overshoot = end === start ? 0 : Math.max(0, (end >= start ? peak - end : end - peak) / Math.abs(end - start));
  return { settledAtMs: Math.round(steps * dt * 1000), overshootPct: Math.round(overshoot * 1000) / 10 };
}

