  const duration = 0.5; // seconds, fixed
  let t = 0, origin = from, target = to, x = from, v = 0;
  return {
    step(dt) { t = Math.min(duration, t + dt); const p = 1 - (1 - t / duration) ** 3; const nx = origin + (target - origin) * p; v = (nx - x) / dt; x = nx; return { x, v }; },
    get position() { return x; }, get velocity() { return v; },
    retarget(next) { origin = x; target = next; t = 0; v = 0; },
    isAtRest() { return t >= duration; },
