codeExercise.solution:
const snaps = [{ name: 'open', y: 0 }, { name: 'half', y: 400 }, { name: 'closed', y: 800 }];
const flickDown = [{ t: 0, y: 300 }, { t: 16, y: 310 }, { t: 32, y: 330 }, { t: 48, y: 360 }, { t: 64, y: 400 }];
const slowDrag = [{ t: 0, y: 340 }, { t: 100, y: 360 }, { t: 200, y: 380 }];
const flickUp = [{ t: 0, y: 500 }, { t: 40, y: 440 }, { t: 80, y: 380 }];
function estimateVelocity(samples, windowMs = 100) {
  if (samples.length < 2) return 0;
  const last = samples[samples.length - 1];
  const first = samples.find(s => last.t - s.t <= windowMs);
  if (!first || first === last) return 0;
  return ((last.y - first.y) / (last.t - first.t)) * 1000;
}
function releaseTarget({ y, samples, snaps, dismissVelocity = 1000, projectionS = 0.2 }) {
  const velocity = estimateVelocity(samples);
  const byY = [...snaps].sort((a, b) => a.y - b.y);
  let chosen;
  if (velocity >= dismissVelocity) chosen = byY[byY.length - 1];
  else if (velocity <= -dismissVelocity) chosen = byY[0];
  else {
    const projected = y + velocity * projectionS;
    chosen = byY.reduce((best, s) => (Math.abs(s.y - projected) < Math.abs(best.y - projected) ? s : best));
  }
  return { target: chosen.name, targetY: chosen.y, initialVelocity: velocity };
}

