  if (samples.length < 2) return 0;
  const a = samples[samples.length - 2], b = samples[samples.length - 1];
  return ((b.y - a.y) / (b.t - a.t)) * 1000;
}
function releaseTarget({ y, samples, snaps }) {
  const nearest = [...snaps].sort((a, b) => Math.abs(a.y - y) - Math.abs(b.y - y))[0]; // position only
  return { target: nearest.name, targetY: nearest.y, initialVelocity: 0 };             // restart from rest
}
```

The starter (nearest snap to the release position, `initialVelocity: 0`) treats the settle as a fresh fixed curve that starts from rest. A flick "dies," and the sheet hitches at release. It reveals **`motion-engineering.m3`**: treating a spring like an easing curve and throwing away the velocity it's meant to carry.

