codeExercise.solution:
function slideIn(fromEdge, distancePx, { reducedMotion = false, rtl = false } = {}) {
  if (reducedMotion) return [{ opacity: 0 }, { opacity: 1 }];
  let from;
  if (fromEdge === 'bottom') from = `translateY(${distancePx}px)`;
  else {
    const startSign = rtl ? 1 : -1;
    from = `translateX(${(fromEdge === 'start' ? startSign : -startSign) * distancePx}px)`;
  }
  return [{ transform: from, opacity: 0 }, { transform: 'none', opacity: 1 }];
}

