codeExercise.solution:
const museumTokens = {
  primitive: { 'color.ink.900': '#1b1a17', 'color.ink.050': '#f7f5f0', 'color.gold.600': '#8a6d1c', 'color.gold.300': '#e0c46c', 'color.white': '#ffffff', 'color.black': '#000000', 'space.4': '16px' },
  semantic: {
    light: { 'color.text.default': '{color.ink.900}', 'color.surface.default': '{color.ink.050}', 'color.accent': '{color.gold.600}' },
    dark: { 'color.text.default': '{color.ink.050}', 'color.surface.default': '{color.ink.900}', 'color.accent': '{color.gold.300}' },
    'high-contrast': { 'color.text.default': '{color.black}', 'color.surface.default': '{color.white}', 'color.accent': '{color.black}' },
  },
  component: {
    'button.primary.bg': '{color.accent}',
    'button.primary.fg': '{color.surface.default}',
    'button.padding.inline': '{space.4}',
    'card.bg': '{color.surface.default}',
    'card.title': '{color.text.default}',
    'link.hover': '{button.primary.bg}',
  },
};
const errorOf = fn => { try { fn(); return 'no error'; } catch (e) { return e.message; } };
function resolveTokens(tokens, theme) {
  const semantic = tokens.semantic[theme];
  if (!semantic) throw new Error(`Unknown theme: ${theme}`);
  const lookup = name => (name in semantic ? semantic[name] : name in tokens.primitive ? tokens.primitive[name] : tokens.component[name]);
  const memo = new Map();
  function resolve(name, path) {
    if (memo.has(name)) return memo.get(name);
    if (path.includes(name)) throw new Error(`Token cycle: ${[...path, name].join(' -> ')}`);
    const raw = lookup(name);
    const ref = /^\{([^}]+)\}$/.exec(String(raw).trim());
    let value = raw;
    if (ref) {
      const target = ref[1];
      if (lookup(target) === undefined) throw new Error(`Unresolved token {${target}} in ${path.length ? path[0] : name}`);
      value = resolve(target, [...path, name]);
    }
    memo.set(name, value);
    return value;
  }
  const out = {};
  for (const name of Object.keys(tokens.component)) out[name] = resolve(name, []);
  return out;
}

codeExercise.solutionNote:
**The plausible wrong answer:**

```js
function resolveTokens(tokens, theme) {
  if (!tokens.semantic[theme]) throw new Error(`Unknown theme: ${theme}`);
  const semantic = tokens.semantic.light; // "tokens are just colour variables": one fixed alias table; themes will "swap the palette"
  const lookup = n => (n in semantic ? semantic[n] : n in tokens.primitive ? tokens.primitive[n] : tokens.component[n]);
  const resolve = (n, path = []) => {
    if (path.includes(n)) throw new Error(`Token cycle: ${[...path, n].join(' -> ')}`);
    const m = /^\{([^}]+)\}$/.exec(String(lookup(n)));
    if (!m) return lookup(n);
    if (lookup(m[1]) === undefined) throw new Error(`Unresolved token {${m[1]}} in ${path[0] || n}`);
    return resolve(m[1], [...path, n]);
  };
  const out = {};
  for (const n of Object.keys(tokens.component)) out[n] = resolve(n);
  return out;
}
```

Dark and high-contrast render exactly like light. It reveals **`design-system-architecture.m3`**: without a semantic tier that varies per theme, "dark mode" becomes a global palette swap (see P1).

