describe('resolveTokens', () => {
  it('resolves component → semantic → primitive', () => {
    expect(resolveTokens(museumTokens, 'light')['button.primary.fg']).toBe('#f7f5f0');
  });
  it('changes values per theme without touching component tokens', () => {
    const light = resolveTokens(museumTokens, 'light'), dark = resolveTokens(museumTokens, 'dark');
    expect(light['card.bg']).toBe('#f7f5f0');
    expect(dark['card.bg']).toBe('#1b1a17');
    expect(Object.keys(light)).toEqual(Object.keys(dark));
  });
  it('resolves non-colour tokens and component-to-component references', () => {
    const r = resolveTokens(museumTokens, 'dark');
    expect(r['button.padding.inline']).toBe('16px');
    expect(r['link.hover']).toBe('#e0c46c');
  });
  it('reports missing references, cycles and unknown themes', () => {
    expect(() => resolveTokens({ ...museumTokens, component: { 'tag.bg': '{color.teal.100}' } }, 'light')).toThrow('Unresolved token {color.teal.100} in tag.bg');
    expect(() => resolveTokens({ ...museumTokens, component: { a: '{b}', b: '{a}' } }, 'light')).toThrow('Token cycle: a -> b -> a');
    expect(() => resolveTokens(museumTokens, 'sepia')).toThrow('Unknown theme: sepia');
  });
});

