codeExercise.solution:
function buttonProps(input = {}) {
  const VARIANTS = ['primary', 'secondary', 'ghost', 'danger'];
  const SIZES = ['sm', 'md', 'lg'];
  const { variant = 'primary', size = 'md', loading = false, disabled = false, iconOnly = false, label, className, icon, iconStart, ...rest } = input; // icon/iconStart render the glyph, not attributes
  if (!VARIANTS.includes(variant)) throw new Error(`Unknown variant: ${variant}`);
  if (!SIZES.includes(size)) throw new Error(`Unknown size: ${size}`);
  if (iconOnly && !label) throw new Error('Icon-only buttons need a label');
  const attrs = { type: 'button' };
  for (const [key, value] of Object.entries(rest)) {
    if (['onClick', 'type', 'id'].includes(key) || key.startsWith('aria-') || key.startsWith('data-')) attrs[key] = value;
    else throw new Error(`Unsupported prop "${key}": use a variant or compose`);
  }
  if (iconOnly) attrs['aria-label'] = label;
  if (loading) { attrs['aria-busy'] = 'true'; attrs['aria-disabled'] = 'true'; }
  if (disabled) attrs.disabled = true;
  const classes = ['btn', `btn--${variant}`, `btn--${size}`];
  if (loading) classes.push('is-loading');
  if (className) classes.push(className);
  return { className: classes.join(' '), attrs };
}

