  const attrs = { type: 'button', ...rest };
  if (style) attrs.style = style;
  if (iconOnly) attrs['aria-label'] = label;
  if (loading) { attrs['aria-busy'] = 'true'; attrs['aria-disabled'] = 'true'; }
  if (disabled) attrs.disabled = true;
  return { className: ['btn', `btn--${variant}`, `btn--${size}`, loading && 'is-loading', className].filter(Boolean).join(' '), attrs };
