codeExercise.solution:
const designVars = { 'color.text.default': '#1B1A17', 'color.surface.default': '#FFF', 'color.accent': '#8a6d1c', 'space.m': '20px', 'space.3xl': '64px', 'color.surface.sunken': '#ece8df' };
const codeTokens = { 'color.text.default': '#1b1a17', 'color.surface.default': '#ffffff', 'color.accent': '#8b6d1c', 'space.m': '1rem', 'color.legacy.link': '#0645ad' };
function normalizeTokenValue(value) {
  let s = String(value).trim().toLowerCase();
  if (/^#[0-9a-f]{3}$/.test(s)) s = '#' + [...s.slice(1)].map(c => c + c).join('');
  const px = /^(-?\d+(?:\.\d+)?)px$/.exec(s);
  if (px) s = `${Number(px[1]) / 16}rem`;
  const rem = /^(-?\d+(?:\.\d+)?)rem$/.exec(s);
  if (rem) s = `${Number(rem[1])}rem`;
  return s;
}
function tokenDrift(design, code) {
  const names = [...new Set([...Object.keys(design), ...Object.keys(code)])].sort();
  const onlyInDesign = [], onlyInCode = [], changed = [];
  for (const name of names) {
    if (!(name in code)) onlyInDesign.push(name);
    else if (!(name in design)) onlyInCode.push(name);
    else if (normalizeTokenValue(design[name]) !== normalizeTokenValue(code[name])) changed.push({ name, design: design[name], code: code[name] });
  }
  return { onlyInDesign, onlyInCode, changed };
}

