function nextVersion(current, changes) {
  const MAJOR = ['removed-component', 'removed-prop', 'renamed-prop', 'changed-prop-type', 'removed-token'];
  const MINOR = ['added-component', 'added-prop', 'deprecated', 'added-token', 'token-value-change'];
  const PATCH = ['bugfix', 'docs'];
  for (const c of changes) if (![...MAJOR, ...MINOR, ...PATCH].includes(c)) throw new Error(`Unknown change type: ${c}`);
  const [major, minor, patch] = current.split('.').map(Number);
  if (changes.some(c => MAJOR.includes(c))) return `${major + 1}.0.0`;
  if (changes.some(c => MINOR.includes(c))) return `${major}.${minor + 1}.0`;
  if (changes.length) return `${major}.${minor}.${patch + 1}`;
  return current;
}

