function migrateButtonProps(props) {
  const SIZE = { small: 'sm', medium: 'md', large: 'lg' };
  const out = {}, warnings = [];
  for (const [key, value] of Object.entries(props)) {
    if (key === 'kind') { out.variant = value === 'outline' ? 'secondary' : value; warnings.push('"kind" is now "variant"'); }
    else if (key === 'size' && value in SIZE) { out.size = SIZE[value]; warnings.push(`size "${value}" is now "${SIZE[value]}"`); }
    else if (key === 'icon') { if (value && props.iconName) out.iconStart = props.iconName; warnings.push('"icon" + "iconName" are now "iconStart"'); }
    else if (key === 'iconName') continue;
    else out[key] = value;
  }
  return { props: out, warnings };
}

describe('migrateButtonProps', () => {
  it('renames kind to variant and maps outline to secondary', () => {
    expect(migrateButtonProps({ kind: 'outline' }).props).toEqual({ variant: 'secondary' });
    expect(migrateButtonProps({ kind: 'danger' }).props).toEqual({ variant: 'danger' });
  });
  it('maps legacy sizes and leaves already-migrated sizes alone', () => {
    expect(migrateButtonProps({ size: 'large' }).props).toEqual({ size: 'lg' });
    expect(migrateButtonProps({ size: 'sm' })).toEqual({ props: { size: 'sm' }, warnings: [] });
