let dialogCount = 0;
function createDialogState({ idPrefix = 'dialog' } = {}) {
  const id = `${idPrefix}-${++dialogCount}`;
  let open = false;
  return {
    get open() { return open; },
    show() { open = true; },
    close() { open = false; return 'trigger'; },
    getTriggerProps() { return { 'aria-haspopup': 'dialog', 'aria-expanded': String(open), 'aria-controls': id }; },
