codeExercise.solution:
function lintCritique(note) {
  const PRINCIPLES = ['hierarchy', 'proximity', 'alignment', 'contrast', 'repetition', 'consistency', 'rhythm', 'measure', 'white space', 'affordance', 'feedback', 'legibility', 'accessibility'];
  const issues = [];
  for (const field of ['observation', 'principle', 'outcome', 'change']) {
    if (!note[field] || !String(note[field]).trim()) issues.push(`missing ${field}`);
  }
  if (note.principle && String(note.principle).trim() && !PRINCIPLES.includes(String(note.principle).trim().toLowerCase())) issues.push(`unknown principle: ${note.principle}`);
  if (note.observation && /\b(i (don't |do not )?(like|love|hate)|ugly|pretty|feels (off|wrong|weird|busy)|looks (bad|off))\b/i.test(note.observation)) issues.push('observation is an opinion');
  if (note.change && String(note.change).trim() && !/\d|\b(move|align|group|increase|decrease|replace|remove|use|swap|add|reduce|limit)/i.test(note.change)) issues.push('change is not concrete');
  return { valid: issues.length === 0, issues };
}

