const attendanceCard = [
  { id: 'title', role: 'heading', size: 24, bold: true, accent: false },
  { id: 'badge', role: 'status', size: 14, bold: true, accent: true },
  { id: 'calendar', role: 'link', size: 16, bold: false, accent: true },
  { id: 'updated', role: 'text', size: 14, bold: false, accent: false },
  { id: 'report', role: 'button', size: 16, bold: true, accent: true },
  { id: 'download', role: 'button', size: 16, bold: true, accent: true },
];
const interactive = els => els.filter(e => e.role === 'button' || e.role === 'link');
const salienceScore = e => (e.size / 16) ** 2 * (e.bold ? 1.4 : 1) * (e.accent ? 1.5 : 1);
function salienceShares(elements) {
  const total = elements.reduce((sum, e) => sum + salienceScore(e), 0);
  return Object.fromEntries(elements.map(e => [e.id, total ? Math.round((salienceScore(e) / total) * 100) : 0]));
}
function focusOn(elements, primaryId) {
  return elements.map(e => (e.id === primaryId
    ? { ...e, bold: true, accent: true }
    : { ...e, accent: false, bold: e.role === 'heading' ? e.bold : false }));
}

