function shipGate(review) {
  const blockers = [];
  if (!review.runs) blockers.push('does not run');
  if (!review.testsPass) blockers.push('tests missing or failing');
  if (review.a11yViolations > 0) blockers.push(`accessibility violations: ${review.a11yViolations}`);
  if (!review.keyboardChecked) blockers.push('keyboard not checked');
  if (!review.usesTokens) blockers.push('hard-coded styles instead of tokens');
  for (const state of ['empty', 'error', 'loading']) if (!(review.states || []).includes(state)) blockers.push(`missing ${state} state`);
  if (!review.reviewedBy) blockers.push('no human review');
  return { ship: blockers.length === 0, blockers };
}

