codeExercise.solution:
function measureCheck(widthPx, fontSizePx, charEm = 0.5) {
  if (!(widthPx > 0) || !(fontSizePx > 0) || !(charEm > 0)) throw new Error('Sizes must be positive');
  const chars = Math.round(widthPx / (fontSizePx * charEm));
  const verdict = chars < 45 ? 'too narrow' : chars > 75 ? 'too wide' : 'comfortable';
  return { chars, verdict };
}

