const P = (id, skills, extra = {}) => ({ id, skills, deep: true, deployed: true, hasCaseStudy: true, updated: 1, ...extra });
const myProjects = [
  P('storyboard-wall', ['realtime', 'data', 'a11y', 'motion'], { isCapstone: true, updated: 13 }),
  P('cwv-changelog', ['performance', 'measurement'], { updated: 6 }),
  P('clinic-widgets', ['a11y', 'testing'], { updated: 7 }),
  P('rest-timer-sheet', ['motion', 'gestures', 'a11y'], { updated: 10 }),
  P('museum-ds', ['systems', 'tokens', 'a11y', 'release'], { updated: 11 }),
  P('todo-clone', ['react'], { deep: false, updated: 12 }),
  P('landing-page', ['css'], { hasCaseStudy: false, updated: 12 }),
  P('bundler', ['tooling', 'graphs'], { updated: 8 }),
];
function curatePortfolio(projects, maxPieces = 5) {
  const chosen = [];
  const covered = new Set();
  const take = p => { chosen.push(p.id); p.skills.forEach(s => covered.add(s)); };
  const capstone = projects.find(p => p.isCapstone);
  if (capstone) take(capstone);
  const pool = projects.filter(p => !p.isCapstone && p.deep && p.deployed && p.hasCaseStudy);
  while (chosen.length < maxPieces) {
    const ranked = pool
      .filter(p => !chosen.includes(p.id))
      .map(p => ({ p, gain: p.skills.filter(s => !covered.has(s)).length }))
      .filter(x => x.gain > 0)
      .sort((x, y) => y.gain - x.gain || y.p.updated - x.p.updated || (x.p.id < y.p.id ? -1 : 1));
    if (!ranked.length) break;
    take(ranked[0].p);
  }
  return chosen;
}

