function findOverlaps(clips) {
  const byTrack = new Map();
  for (const clip of clips) {
    if (!byTrack.has(clip.track)) byTrack.set(clip.track, []);
    byTrack.get(clip.track).push(clip);
  }
  const pairs = [];
  for (const list of byTrack.values()) {
    list.sort((a, b) => a.start - b.start || (a.id < b.id ? -1 : 1));
    let active = [];
    for (const clip of list) {
      active = active.filter(a => a.end > clip.start); // invariant: active clips haven't ended before this start
      for (const a of active) pairs.push([a.id, clip.id]);
      active.push(clip);
    }
  }
  return pairs.sort((x, y) => (x[0] < y[0] ? -1 : x[0] > y[0] ? 1 : x[1] < y[1] ? -1 : x[1] > y[1] ? 1 : 0));
}

