    const xs = minMaxDecimate(series, 20).map(p => p.x);
    expect(xs).toEqual([...xs].sort((a, b) => a - b));
  });
  it('returns at most 2 × buckets points, and small inputs unchanged', () => {
    expect(minMaxDecimate(series, 20).length).toBeLessThanOrEqual(40);
    const small = [{ x: 0, y: 1 }, { x: 1, y: 2 }];
    expect(minMaxDecimate(small, 5)).toEqual(small);
    expect(minMaxDecimate([], 5)).toEqual([]);
  });
});

