describe('screenplay ops', () => {
  const replay = (doc, ops) => ops.reduce((d, op) => applyOp(d, op).doc, doc);
  it('round-trips a delete through its inverse', () => {
    const { doc, inverse } = applyOp('INT. KITCHEN - NIGHT', { type: 'delete', pos: 5, length: 10 });
    expect(doc).toBe('INT. NIGHT');
    expect(applyOp(doc, inverse).doc).toBe('INT. KITCHEN - NIGHT');
  });
  it('undoes a sequence of operations in reverse order', () => {
    const start = 'EXT. PIER - DAY';
    const { doc, undo } = applyAll(start, [
      { type: 'insert', pos: 5, text: 'OLD ' },
      { type: 'delete', pos: 0, length: 5 },
      { type: 'insert', pos: 0, text: 'INT. ' },
    ]);
    expect(doc).toBe('INT. OLD PIER - DAY');
    expect(replay(doc, undo)).toBe(start);
  });
  it('clamps positions and lengths to the document', () => {
    expect(applyOp('DAY', { type: 'insert', pos: 99, text: '!' }).doc).toBe('DAY!');
    const r = applyOp('DAY', { type: 'delete', pos: 1, length: 99 });
    expect(r.doc).toBe('D');
    expect(applyOp(r.doc, r.inverse).doc).toBe('DAY');
  });
  it('rejects unknown operations', () => {
    expect(() => applyOp('x', { type: 'bold', pos: 0 })).toThrow('Unknown op: bold');
  });
});

codeExercise.solution:
function applyOp(doc, op) {
  if (op.type === 'insert') {
    const pos = Math.max(0, Math.min(op.pos, doc.length));
    return { doc: doc.slice(0, pos) + op.text + doc.slice(pos), inverse: { type: 'delete', pos, length: op.text.length } };
  }
  if (op.type === 'delete') {
    const pos = Math.max(0, Math.min(op.pos, doc.length));
    const removed = doc.slice(pos, pos + Math.max(0, op.length));
    return { doc: doc.slice(0, pos) + doc.slice(pos + removed.length), inverse: { type: 'insert', pos, text: removed } };
  }
  throw new Error(`Unknown op: ${op.type}`);
}
function applyAll(doc, ops) {
  const undo = [];
  for (const op of ops) { const r = applyOp(doc, op); doc = r.doc; undo.unshift(r.inverse); }
  return { doc, undo };
}
